package com.gamingevents.dto;
import jakarta.validation.constraints.*;
public final class GameDtos { private GameDtos(){} public record ProfileRequest(@NotBlank String username,String profileImage,String favoriteGame,String skillLevel){} public record ProfileResponse(Long id,String username,String profileImage,String favoriteGame,String skillLevel,int totalMatches,int wins,int losses,int rankingPoints){} public record MatchRequest(@NotNull Long tournamentId,@NotNull Long playerOneId,@NotNull Long playerTwoId,@NotBlank String roundName){} public record ResultRequest(@NotNull Long winnerId){} public record MatchResponse(Long id,Long tournamentId,String playerOne,String playerTwo,String winner,String roundName,String status){} public record RankingResponse(int rank,String username,int points,int wins,int losses){} public record UserStatusRequest(boolean enabled){} }
